                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((color, cells))

    # Small detached pieces take the color of the nearest larger object.
    for color, cells in comps:
        if len(cells) > 2:
            continue
        candidates = [(co, ob) for co, ob in comps if co != color and len(ob) > len(cells)]
